	}
	if g.ple != nil {
		if err := g.ple.Speculate(on); err != nil {
			if g.dn != nil {
				_ = g.dn.Speculate(!on)
			}
			return err
		}
	}
	g.dropPrerecorded()
	g.spec = on
	return nil
}

