	// tower yields the device between slices, and rule 1 treats each of
	// these as an interactive job, so no background unit starts in a gap.
	towers  int
	arrival uint64
	closed  bool
	stopped chan struct{}
	// restores counts checkpoint restores, and batches and batchRows the
	// batched decode passes and the rows they carried, for a test that has
