	// carry it, which is why `slots` is set before `alloc` and not by a
	// setter. The slots of one layer are **adjacent**, so a slot is a layer's
	// base plus a stride and neither the kernels nor the staging notice.
	if g.slots <= 0 {
		g.slots = 1
	}
	g.winStride = hist * g.qkvN()
	g.stateStride = c.StateSize()
	g.aWin = alloc(nLayers * g.slots * g.winStride)
	g.aNorm = alloc(rows * cw)
	g.aSilu = alloc(rows * cw)
	g.aOut = alloc(rows * c.Inner)
	g.aGate = alloc(rows * c.NHeadV)
	g.aBeta = alloc(rows * c.NHeadV)
	g.aState = alloc(nLayers * g.slots * g.stateStride)
	g.aResult = alloc(rows * c.NEmbd)
	// The decode GEMV's partial sums, f32 [KSLABS][gemmN] (L8d-4). The wider
	// of the two projections is the fused one, so 32 x 16512 x 4 = 2.1 MB —
// constant so the recorded decode step is byte-identical every token (P1c).
func (g *DeltaNetGPU) writeSeq() { g.abuf.WriteUint32At(0, []uint32{uint32(g.past)}) }

// stateAt and winAt are a layer's two carried tensors in a given slot.
func (g *DeltaNetGPU) stateAt(layer, slot int) uint32 {
	return g.layers[layer].state + uint32(slot*g.stateStride)
}

func (g *DeltaNetGPU) winAt(layer, slot int) uint32 {
	return g.layers[layer].win + uint32(slot*g.winStride)
}

// stateDst is the slot the next pass writes: the live one in an ordinary
// pass, the other one while a speculative pass is in flight.
func (g *DeltaNetGPU) stateDst() int {
	if g.stateSpec {
		return (g.stateSlot + 1) % g.slots
	}
	return g.stateSlot
}

// midSlot is where a keep-prefix pass stores its state after row 1+i (P20b).
func (g *DeltaNetGPU) midSlot(i int) int { return (g.stateSlot + 2 + i) % g.slots }

// keepPush sets SEQ_KEEP_FIRST and the mid slots on a scan or ring-write push
// of a speculative pass (P20c/P20b); at is stateAt or winAt.
func (g *DeltaNetGPU) keepPush(pc *push, layer int, at func(layer, slot int) uint32) error {
	if !g.stateSpec || !g.keepFirst {
		return nil
	}
	mids := maxInt(0, g.rows-2)
	if mids > g.slots-2 || mids > 2 {
		return fmt.Errorf("llm: a keep-prefix pass of %d rows needs %d deltanet slots, %d are staged",
			g.rows, mids+2, g.slots)
	}
	pc.LDALo = uint32(1 + mids) // SEQ_KEEP_FIRST
	if mids > 0 {
		pc.GateOff = at(layer, g.midSlot(0)) // SSM_STATE_MID0 / SEQ_HIST_MID0
	}
	if mids > 1 {
		pc.BOff = at(layer, g.midSlot(1))
	}
	return nil
}

// Speculate makes the next passes rewindable: they read the committed slot of
// every layer's recurrent state and convolution ring and write the other one,
// so that discarding a pass is doing nothing at all (P5c). CommitSlot then
// makes what the pass wrote the committed slot, and nothing else does.
//
// It is off in decode and in prefill, where the pass *is* the commit — and it
// has to be, because the two slots are different push constants and P1c's
// pre-recorded decode step is the same bytes every token.
func (g *DeltaNetGPU) Speculate(on bool) error {
	if on && g.seqSlots {
		return fmt.Errorf("llm: this block's slots are sequences (GraphOpts.Slots); it cannot also speculate")
	}
	if on && g.slots < 2 {
		return fmt.Errorf("llm: this block was staged with one state slot; a rewindable pass needs two " +
			"(GraphOpts.Speculative)")
	}
	g.stateSpec = on
	return nil
}

func (g *DeltaNetGPU) Speculating() bool { return g.stateSpec }

// KeepFirst makes every speculative pass also leave its first row folded into
// the committed slot (P20c), which is what lets Graph.KeepFirst accept row 0
// of a pass without re-running it. A pass of more rows than the ring holds
// would not store row 0 in the ring at all, so the graph refuses those.
func (g *DeltaNetGPU) KeepFirst(on bool) { g.keepFirst = on }

// RingRows is the convolution's history length, the most rows a keep-first
// pass may carry.
func (g *DeltaNetGPU) RingRows() int { return g.cfg.Conv - 1 }

// CommitSlot accepts whatever the last speculative pass wrote.
func (g *DeltaNetGPU) CommitSlot() {
	if g.stateSpec {
		g.stateSlot = g.stateDst()
	}
}

// KeepSlot accepts the first k of a keep-prefix pass's `rows` rows (P20b):
// row 0 is already in the slot it read, all of them in the destination, and
// rows 0..k-1 in mid slot k-2.
func (g *DeltaNetGPU) KeepSlot(k, rows int) {
	switch {
	case !g.stateSpec || k <= 1:
	case k >= rows:
		g.CommitSlot()
	default:
		g.stateSlot = g.midSlot(k - 2)
	}
}

// StateSlot is which of the two slots is committed, for a test that wants to
// see the ping-pong rather than infer it.
func (g *DeltaNetGPU) StateSlot() int { return g.stateSlot }

// CarriedLen is how many float32s one sequence carries through this block
// from pass to pass: every layer's recurrent state and convolution ring.
// SaveCarried and RestoreCarried copy the live slot's to and from the host,
// which is what a sequence checkpoint is made of (CONCURRENCY.md C4). The
// arena is host-cached, so this is a memcpy and not a readback.
func (g *DeltaNetGPU) CarriedLen() int { return len(g.layers) * (g.stateStride + g.winStride) }

func (g *DeltaNetGPU) SaveCarried(dst []float32) error {
	if len(dst) != g.CarriedLen() {
		return fmt.Errorf("llm: %d values against a %d-value deltanet checkpoint", len(dst), g.CarriedLen())
	}
	o := 0
	for l := range g.layers {
		g.abuf.ReadFloat32Into(int(g.stateAt(l, g.stateSlot)), dst[o:o+g.stateStride])
		o += g.stateStride
		g.abuf.ReadFloat32Into(int(g.winAt(l, g.stateSlot)), dst[o:o+g.winStride])
		o += g.winStride
	}
	return nil
}

func (g *DeltaNetGPU) RestoreCarried(src []float32) error {
	if len(src) != g.CarriedLen() {
		return fmt.Errorf("llm: a %d-value deltanet checkpoint against %d", len(src), g.CarriedLen())
	}
	o := 0
	for l := range g.layers {
		g.abuf.WriteFloat32At(int(g.stateAt(l, g.stateSlot)), src[o:o+g.stateStride])
		o += g.stateStride
		g.abuf.WriteFloat32At(int(g.winAt(l, g.stateSlot)), src[o:o+g.winStride])
		o += g.winStride
	}
	return nil
}

// Reset zeroes one layer's recurrent state and the convolution's window,
// which is what a fresh sequence starts from.
//
// The window would not strictly need clearing — a tap that reaches before
// position zero contributes nothing whatever the ring holds — but this is
// 198 KB a layer against a 3.1 MB state, and `State` below is easier to
// believe when the two agree about what an empty sequence looks like.
func (g *DeltaNetGPU) Reset(layer int) error {
	if layer < 0 || layer >= len(g.layers) {
		return fmt.Errorf("llm: layer %d of %d", layer, len(g.layers))
	}
	c := g.cfg
	// Both slots (P5c), so that a fresh sequence does not depend on which of
	// them the last one happened to leave committed. Which slot is live is
	// deliberately *not* touched here: Reset is per layer and the ping-pong
	// is not, so a caller resetting one layer of 36 must not move it.
	//
	// Sequence slots are the exception (CONCURRENCY.md C1): each is another
	// conversation, live in some other request, so only the one being
	// started is cleared.
	lo, hi := 0, g.slots
	if g.seqSlots {
		lo, hi = g.stateSlot, g.stateSlot+1
	}
	for slot := lo; slot < hi; slot++ {
		g.abuf.ZeroFloat32At(int(g.stateAt(layer, slot)), c.StateSize())
		g.abuf.ZeroFloat32At(int(g.winAt(layer, slot)), (c.Conv-1)*g.qkvN())
	}
	return nil
}

