		Speculative: true, SpecRows: 3})
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(g.Destroy)
	if err := g.PinSchedule(true); err != nil {
		t.Fatal(err)
	}
	norm, err := g.Hidden(ids)
	if err != nil {
		t.Fatal(err)
	}
