}

// Begin starts decoding with `first`, the token the prefill's last logits
// named and the trunk has not run.
func (s *Speculator) Begin(first int32) error {
	if s.d.Past() != s.g.Past() && s.slot >= 0 {
		if err := s.useSlot(); err != nil {
			return err
		}
	}
	if got, want := s.d.Past()+len(s.oweX), s.g.Past(); got != want {
		return fmt.Errorf("llm: the draft is at %d and the trunk at %d", got, want)
	}
	if len(s.h) != s.wide {
		return fmt.Errorf("llm: beginning without the trunk's residual")
	}
	if err := s.g.SpeculateFirst(true); err != nil {
		return err
	}
	s.pend = append(s.pend[:0], first)
